<?php use App\Core\Csrf; $customer=$order['company_name']?:$order['contact_name']; $billing=$order['billing_type']==='one_off'?'One-off payment':ucfirst((string)$order['billing_interval']).' recurring'; ?>
<header class="page-header order-header"><div><a class="back-link" href="/orders">← Customer Orders</a><div class="profile-title"><span class="profile-avatar order-avatar">◇</span><div><div class="eyebrow"><?= htmlspecialchars((string)$order['order_number']) ?></div><h1><?= htmlspecialchars((string)$order['description']) ?></h1><p><?= htmlspecialchars((string)$customer) ?> · <?= htmlspecialchars($billing) ?></p></div></div></div><div class="header-actions"><?php if($order['invoice_id']): ?><a class="primary-button" href="/invoices/<?= (int)$order['invoice_id'] ?>">View invoice</a><?php endif; ?><a class="secondary-button" href="/orders/<?= (int)$order['id'] ?>/edit">Edit order</a><span class="status <?= htmlspecialchars((string)$order['status']) ?>"><?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$order['status']))) ?></span></div></header>
